// Map to lookup embedded packs
static std::map<std::string, const char*> embeddedPacks = {
    {"en-US", EMBEDDED_en_US},
    {"zh-CN", EMBEDDED_zh_CN},
    {"zh-TW", EMBEDDED_zh_TW},
    {"ja-JP", EMBEDDED_ja_JP},
    {"ko-KR", EMBEDDED_ko_KR},
    {"fr-FR", EMBEDDED_fr_FR},
    {"de-DE", EMBEDDED_de_DE},
    {"es-ES", EMBEDDED_es_ES},
    {"ru-RU", EMBEDDED_ru_RU},
    {"pt-PT", EMBEDDED_pt_PT},
    {"lk-CN", EMBEDDED_lk_CN},
    {"it-IT", EMBEDDED_it_IT}
};

std::string getEmbeddedLanguagePack(const std::string& languageCode) {
    auto it = embeddedPacks.find(languageCode);
    if (it != embeddedPacks.end()) {
        return std::string(it->second);
    }
    return std::string();  // Return empty if not found
}

bool isLanguagePackEmbedded(const std::string& languageCode) {
    return embeddedPacks.find(languageCode) != embeddedPacks.end();
}